function load(){try{state=Object.assign(state,JSON.parse(localStorage.getItem('AKSANTARA_STATE')||'{}'))}catch(e){}; if(!state.province)state.province=1;}
function save(){localStorage.setItem('AKSANTARA_STATE',JSON.stringify(state));}
function baseProv(n=state.province){return PROVINCES.find(p=>p.n==n)||PROVINCES[0]}
function p(){const b=baseProv(); const c=state.custom[b.n]||{}; return {...b,...c,samples:c.samples||b.samples}}
function toast(t){const el=$('#toast'); el.textContent=t; el.style.display='block'; clearTimeout(window.__toast); window.__toast=setTimeout(()=>el.style.display='none',2200)}
function go(id){const target=document.getElementById(id); if(target) target.scrollIntoView({behavior:'smooth',block:'start'}); $$('#nav button, nav button').forEach(b=>b.classList.toggle('active',b.dataset.go===id));}
function setProvince(n){state.province=+n; state.selectedSamples=[]; save(); updateAll();}
function renderOptions(){['studioSelect','voiceSelect','qrSelect','adminSelect'].forEach(id=>{const el=$('#'+id); if(!el)return; el.innerHTML=PROVINCES.map(pr=>`<option value="${pr.n}">${pr.n}. ${pr.name} — ${pr.aksara}</option>`).join(''); el.value=state.province;});}
function renderZones(){ $('#zoneGrid').innerHTML=ZONES.map(z=>`<article class="zoneCard"><div class="zoneIcon">${z.icon}</div><small>${z.n}</small><h3>${z.title}</h3><p>${z.desc}</p><button class="btn" data-go="${z.go}">${z.btn} ›</button></article>`).join('');}
function renderFilters(){ $('#filters').innerHTML=REGIONS.map(r=>`<button class="filter ${state.region===r?'active':''}" data-region="${r}">${r}</button>`).join('');}
function filtered(){const q=($('#search')?.value||'').toLowerCase(); return PROVINCES.filter(pr=>(state.region==='All'||pr.region===state.region)&&(`${pr.name} ${pr.region} ${pr.aksara} ${pr.wisdom} ${pr.story}`.toLowerCase().includes(q)));}
function renderCards(){ $('#cards').innerHTML=filtered().map(pr=>`<button class="card ${pr.n===state.province?'active':''}" data-prov="${pr.n}"><b>${pr.name}</b><span>${pr.aksara} • ${pr.wisdom}</span></button>`).join('');}
function renderMap(){renderCards(); const layer=$('#hotspotLayer'); layer.innerHTML=PROVINCES.map(pr=>`<button class="hotspot ${pr.n===state.province?'active':''}" style="left:${pr.x}%;top:${pr.y}%" data-prov="${pr.n}" title="${pr.name}">${pr.n}</button>`).join(''); const pr=p(); $('#selectedChips').innerHTML=`<button class="chip" data-prov="${pr.n}">Province ${pr.n}: ${pr.name}</button><button class="chip">${pr.region}</button><button class="chip">${pr.aksara}</button><button class="chip">${pr.wisdom}</button><button class="chip" data-go="studio">Aksara Studio linked</button><button class="chip" data-go="skills">Skills linked</button><button class="chip" data-go="voice">Voice linked</button><button class="chip" data-go="qr">QR linked</button>`;}
function samples(){return p().samples||[];}
function renderSamples(){const ss=samples(); $('#sampleGrid').innerHTML=ss.map((s,i)=>`<button class="sample ${state.selectedSamples.includes(i)?'active':''}" data-sample="${i}" title="${s.meaning}">${s.ch}</button>`).join('');}
function updateStudio(){const pr=p(); $('#studioSelect').value=pr.n; $('#studioTitle').textContent=`${pr.name} — ${pr.aksara}`; $('#studioDesc').innerHTML=`This studio promotes <b>${pr.aksara}</b> as a gateway to ${pr.wisdom}. Click samples, use keyboard controls, or type directly.`; renderSamples(); translateWorkspace(false);}
function insertAtCursor(text){const w=$('#workspace'); w.focus(); document.execCommand('insertText',false,text);}
function applySample(i){const s=samples()[i]; if(!s)return; if(!state.selectedSamples.includes(i)) state.selectedSamples.push(i); insertAtCursor(s.ch+' '); save(); renderSamples(); translateWorkspace(false); toast(`${s.ch} inserted.`);}
function tokenMeaning(token){for(const s of samples()){if(s.ch===token)return s} for(const pr of PROVINCES){for(const s of ((state.custom[pr.n]&&state.custom[pr.n].samples)||pr.samples)){if(s.ch===token)return s}} return null;}
function translateWorkspace(showToast=true){const txt=$('#workspace').textContent.trim(); if(!txt){$('#translationBox').innerHTML='<b>Meaning / Translation:</b><br>Select or type aksara samples. Translation results will appear here.';return} const tokens=txt.split(/\s+/).filter(Boolean); const known=tokens.map(t=>({t,s:tokenMeaning(t)})); const meanings=known.map(k=>k.s?k.s.meaning:`unregistered symbol ${k.t}`); const pr=p(); const en=`${pr.name} communicates ${meanings.join(', ')} through ${pr.aksara} and ${pr.wisdom}.`; const id=`${pr.name} mengomunikasikan ${meanings.join(', ')} melalui ${pr.aksara} dan ${pr.wisdom}.`; $('#translationBox').innerHTML=`<b>Selected Aksara:</b> ${tokens.join(' ')}<br><b>Meaning sequence:</b> ${meanings.join(' • ')}<br><b>EN:</b> ${en}<br><b>ID:</b> ${id}`; if(showToast)toast('Translation generated from written aksara.');}
function updateSkills(){const pr=p(); $('#skillTabs').innerHTML=SKILLS.map(s=>`<button class="skillTab ${state.skill===s?'active':''}" data-skill="${s}">${s}</button>`).join(''); $('#skillProvince').innerHTML=`<b>${pr.name}</b><br>${pr.aksara}<br>${pr.wisdom}`; const done=SKILLS.filter(s=>state.progress[pr.n+'-'+s]).length; $('#skillProgress').style.width=(done/SKILLS.length*100)+'%'; $('#skillDone').textContent=`${done} of ${SKILLS.length} assessments completed`; renderTask();}
function renderTask(){const pr=p(), sk=state.skill, key=pr.n+'-'+sk; let html=''; if(sk==='Listening') html=`<h3>Listening Assessment: ${pr.story}</h3><p>Listen to the line, then answer the comprehension question.</p><button class="btn primary" data-speak="The province teaches cultural communication through ${pr.wisdom}.">Play Listening Text</button><button class="choice" data-answer="1">The province teaches cultural communication through local wisdom.</button><button class="choice" data-answer="0">The province rejects English learning.</button><button class="choice" data-answer="0">The province has no oral tradition.</button>`; if(sk==='Speaking') html=`<h3>Speaking Assessment</h3><p>Record or write a 40-word speaking script explaining how ${pr.name} can share ${pr.wisdom} internationally.</p><textarea class="taskInput" id="assessmentText" placeholder="Write at least 40 words..."></textarea><button class="btn primary" data-submit-text="40">Submit Speaking Script</button>`; if(sk==='Reading') html=`<h3>Reading Assessment</h3><p>${pr.name} uses ${pr.aksara} and ${pr.story.toLowerCase()} to connect local identity with global English communication. Learners analyze how local knowledge becomes a bridge for intercultural understanding.</p><button class="choice" data-answer="1">Local identity can support global communication.</button><button class="choice" data-answer="0">Local identity must be removed.</button>`; if(sk==='Writing') html=`<h3>Writing Assessment</h3><p>Write a 90-word academic paragraph about ${pr.aksara}, ${pr.wisdom}, and English learning.</p><textarea class="taskInput" id="assessmentText" placeholder="Write at least 90 words..."></textarea><button class="btn primary" data-submit-text="90">Submit Writing</button>`; if(sk==='Vocabulary') html=`<h3>Vocabulary Assessment</h3><p>Type five keywords related to ${pr.wisdom}, separated by commas.</p><input class="taskInput" id="assessmentText" placeholder="heritage, identity, ..."><button class="btn primary" data-submit-vocab="5">Submit Vocabulary</button>`; if(sk==='Intercultural') html=`<h3>Intercultural Reflection</h3><p>How can ${pr.name} share ${pr.wisdom} with international audiences without losing local identity?</p><textarea class="taskInput" id="assessmentText" placeholder="Write at least 60 words..."></textarea><button class="btn primary" data-submit-text="60">Submit Reflection</button>`; $('#taskContent').innerHTML=html+(state.progress[key]?'<p class="ok">Assessment completed.</p>':'');}
function completeSkill(){state.progress[p().n+'-'+state.skill]=true; save(); updateSkills(); updateAdmin(); toast('Assessment completed.');}
function wordCount(t){return (t.trim().match(/\S+/g)||[]).length}
function updateVoice(){const pr=p(); $('#voiceSelect').value=pr.n; $('#voiceTitle').textContent=`${pr.name} Voice Atlas`; $('#voiceSentence').innerHTML=`Model line: <b>${pr.name}</b> connects ${pr.aksara} and ${pr.wisdom} with intelligible English communication.`; $('#pronFocus').textContent=pr.focus; const sc=state.recordings[pr.n]||state.voiceUploads[pr.n]?88:0; $('#voiceScoreBar').style.width=sc+'%'; $('#voiceScore').textContent=sc?`Local sample available. Estimated clarity ${sc}%.`:'Record/upload a local accent sample for this province.'; renderVoices();}
function renderVoices(){const sel=$('#voiceChoice'); if(!sel)return; voices=speechSynthesis.getVoices(); sel.innerHTML='<option value="">Auto natural browser voice</option>'+voices.map((v,i)=>`<option value="${i}">${v.name} — ${v.lang}</option>`).join('');}
function speakText(text){speechSynthesis.cancel(); const u=new SpeechSynthesisUtterance(text); const idx=$('#voiceChoice').value; if(idx!==''&&voices[idx])u.voice=voices[idx]; u.lang=(u.voice&&u.voice.lang)||'en-US'; u.rate=.86; u.pitch=.95; speechSynthesis.speak(u); $('#voiceStatus').textContent='Playing model line with selected browser voice.';}
async function startRecord(){try{const stream=await navigator.mediaDevices.getUserMedia({audio:true}); recorder=new MediaRecorder(stream); recChunks=[]; recorder.ondataavailable=e=>recChunks.push(e.data); recorder.onstop=()=>{const blob=new Blob(recChunks,{type:'audio/webm'}); const reader=new FileReader(); reader.onload=()=>{state.recordings[p().n]=reader.result; save(); updateVoice(); toast('Local accent recording saved.');}; reader.readAsDataURL(blob); stream.getTracks().forEach(t=>t.stop());}; recorder.start(); $('#voiceStatus').textContent='Recording local accent...';}catch(e){toast('Recording permission unavailable.')}}
function stopRecord(){if(recorder&&recorder.state==='recording')recorder.stop();}
function playRecorded(){const data=state.recordings[p().n]||state.voiceUploads[p().n]; if(!data){toast('No recorded/uploaded voice for this province.');return} new Audio(data).play();}
function updateAI(){const pr=p(); $('#chat').innerHTML=`<div class="msg"><b>AKSANTARA AI:</b> Welcome. We are exploring ${pr.name}. Ask for a story, vocabulary, speaking prompt, writing model, or feedback.</div>`; $('#promptButtons').innerHTML=['Create a speaking prompt','Explain the local wisdom','Give five vocabulary words','Make a writing model','Design an intercultural question','Give feedback on my paragraph'].map(x=>`<button class="prompt" data-prompt="${x}">${x}</button>`).join('');}
function aiAnswer(q){const pr=p(); q=q.toLowerCase(); if(q.includes('vocab'))return `Five keywords for ${pr.name}: heritage, wisdom, identity, dialogue, intelligibility.`; if(q.includes('story'))return `${pr.story} can be retold as a short English narrative about ${pr.wisdom}.`; if(q.includes('speaking'))return `Speaking prompt: Explain how ${pr.aksara} and ${pr.wisdom} can introduce ${pr.name} to international visitors in clear, intelligible English.`; if(q.includes('writing'))return `Model: ${pr.name} shows how local scripts and cultural wisdom can support English learning. Through ${pr.aksara}, learners connect identity, communication, and future-oriented literacy.`; if(q.includes('feedback'))return `Feedback guide: check clarity, topic sentence, cultural accuracy, transitions, and intelligibility. Add one example from ${pr.story}.`; return `${pr.name} connects ${pr.aksara}, ${pr.wisdom}, and English communication. You can develop this into listening, speaking, reading, writing, vocabulary, or intercultural tasks.`;}
function sendAI(){const q=$('#aiInput').value.trim(); if(!q)return; $('#chat').insertAdjacentHTML('beforeend',`<div class="msg"><b>You:</b> ${q}</div><div class="msg"><b>AKSANTARA AI:</b> ${aiAnswer(q)}</div>`); $('#aiInput').value=''; $('#chat').scrollTop=$('#chat').scrollHeight;}
function updateQR(){const pr=p(); $('#qrSelect').value=pr.n; $('#qrProvince').textContent=`${pr.name} • ${pr.aksara}`; $('#qrImg').src=`assets/qr/${String(pr.n).padStart(2,'0')}.png`; $('#qrCaption').textContent=`${pr.wisdom}. ${pr.story}. Voice focus: ${pr.focus}.`; $('#qrDetails').innerHTML=`<button class="seedInfo" data-go="studio"><b>Aksara Studio</b><br>${pr.aksara}</button><button class="seedInfo" data-go="skills"><b>Skills Lab</b><br>${pr.wisdom}</button><button class="seedInfo" data-go="voice"><b>Voice Atlas</b><br>${pr.focus}</button><button class="seedInfo" data-go="ai"><b>AI Tutor</b><br>${pr.story}</button><div class="info"><b>QR payload:</b> ${pr.name}, ${pr.aksara}, ${pr.wisdom}, ${pr.story}, ${pr.focus}.</div>`;}
function updateAdmin(){const pr=p(); $('#adminSelect').value=pr.n; $('#adminProvince').textContent=pr.name; const done=SKILLS.filter(s=>state.progress[pr.n+'-'+s]).length; $('#adminCompleted').textContent=done+'/'+SKILLS.length; $('#adminWisdom').value=pr.wisdom; $('#adminStory').value=pr.story; $('#adminFocus').value=pr.focus; renderMaterials();}
function renderMaterials(){const list=state.materials[p().n]||[]; $('#materialList').innerHTML=list.map((m,i)=>`<div class="material-item"><b>${m.title}</b><p>${m.body}</p><button class="btn" data-remove-material="${i}">Remove</button></div>`).join('')||'<p>No custom materials yet.</p>';}
function updateAll(){renderOptions();renderFilters();renderMap();updateStudio();updateSkills();updateVoice();updateAI();updateQR();updateAdmin();}
function saveStudioPNG(){const pr=p(); const txt=$('#workspace').textContent.trim()||'AKSANTARA'; const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="900"><rect width="100%" height="100%" fill="#061915"/><text x="700" y="120" fill="#f7df80" font-size="54" text-anchor="middle" font-family="Georgia">${pr.name} — ${pr.aksara}</text><text x="700" y="450" fill="#fff4c9" font-size="96" text-anchor="middle" font-family="Georgia">${txt.replace(/[&<>]/g,'')}</text><text x="700" y="780" fill="#20ded0" font-size="30" text-anchor="middle" font-family="Arial">AKSANTARA © Dr. Joko Slamet</text></svg>`; downloadBlob(svg,'AKSANTARA-Studio.svg','image/svg+xml')}
function downloadBlob(data,name,type){const blob=new Blob([data],{type}); const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=name; a.click();}
function downloadQRCard(){const pr=p(); const c=document.createElement('canvas'); c.width=1200;c.height=1600; const ctx=c.getContext('2d'); const img=new Image(); img.onload=()=>{ctx.fillStyle='#061915';ctx.fillRect(0,0,1200,1600);ctx.strokeStyle='#f7df80';ctx.lineWidth=8;ctx.strokeRect(60,60,1080,1480);ctx.fillStyle='#f7df80';ctx.font='bold 70px Georgia';ctx.textAlign='center';ctx.fillText('AKSANTARA',600,170);ctx.font='32px Arial';ctx.fillText(`${pr.name} • ${pr.aksara}`,600,240);ctx.fillStyle='#fff';ctx.fillRect(330,315,540,540);ctx.drawImage(img,360,345,480,480);ctx.fillStyle='#f7df80';ctx.font='bold 32px Arial';wrap(ctx,`${pr.wisdom}. ${pr.story}. Voice focus: ${pr.focus}.`,600,940,850,45);c.toBlob(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`AKSANTARA-QR-${pr.name}.png`;a.click();});};img.src=`assets/qr/${String(pr.n).padStart(2,'0')}.png`;}
function wrap(ctx,text,x,y,max,line){let words=text.split(' '),l=''; for(const w of words){let t=l+w+' '; if(ctx.measureText(t).width>max){ctx.fillText(l,x,y);l=w+' ';y+=line}else l=t} ctx.fillText(l,x,y)}
function wire(){document.addEventListener('click',e=>{const goEl=e.target.closest('[data-go]'); if(goEl){go(goEl.dataset.go);return} const prov=e.target.closest('[data-prov]'); if(prov){setProvince(prov.dataset.prov);return} const fil=e.target.closest('.filter'); if(fil){state.region=fil.dataset.region;renderFilters();renderCards();return} const smp=e.target.closest('[data-sample]'); if(smp){applySample(+smp.dataset.sample);return} const key=e.target.closest('[data-key]'); if(key){const k=key.dataset.key;if(k==='space')insertAtCursor(' ');if(k==='break')insertAtCursor('\n');if(k==='back')document.execCommand('delete',false);translateWorkspace(false);return} const sk=e.target.closest('[data-skill]'); if(sk){state.skill=sk.dataset.skill;updateSkills();return} const ans=e.target.closest('[data-answer]'); if(ans){ans.dataset.answer==='1'?completeSkill():toast('Try again. Read carefully.');return} const st=e.target.closest('[data-submit-text]'); if(st){const min=+st.dataset.submitText; wordCount($('#assessmentText').value)>=min?completeSkill():toast(`Write at least ${min} words.`);return} const sv=e.target.closest('[data-submit-vocab]'); if(sv){($('#assessmentText').value.split(',').filter(x=>x.trim()).length>=+sv.dataset.submitVocab)?completeSkill():toast('Type at least five comma-separated vocabulary words.');return} const sp=e.target.closest('[data-speak]'); if(sp){speakText(sp.dataset.speak);return} const prompt=e.target.closest('.prompt'); if(prompt){$('#aiInput').value=prompt.dataset.prompt; sendAI(); return} const rem=e.target.closest('[data-remove-material]'); if(rem){state.materials[p().n].splice(+rem.dataset.removeMaterial,1);save();renderMaterials();return}});
$('#menuBtn').onclick=()=>$('#nav').classList.toggle('open'); $('#search').oninput=renderCards; ['studioSelect','voiceSelect','qrSelect','adminSelect'].forEach(id=>$('#'+id).onchange=e=>setProvince(e.target.value)); $('#qrApply').onclick=()=>setProvince($('#qrSelect').value); $('#copyAllAksara').onclick=()=>{navigator.clipboard?.writeText(samples().map(s=>`${s.ch} — ${s.meaning}`).join('\n'));toast('All samples copied.')}; $('#copyWritten').onclick=()=>{navigator.clipboard?.writeText($('#workspace').textContent.trim());toast('Written aksara copied.')}; $('#translateBtn').onclick=()=>translateWorkspace(true); $('#clearStudio').onclick=()=>{$('#workspace').textContent='';state.selectedSamples=[];renderSamples();translateWorkspace(false)}; $('#saveStudio').onclick=saveStudioPNG; $('#playVoice').onclick=()=>speakText(`${p().name} connects ${p().aksara} and ${p().wisdom} with intelligible English communication.`); $('#stopVoice').onclick=()=>speechSynthesis.cancel(); $('#recordVoice').onclick=startRecord; $('#stopRecord').onclick=stopRecord; $('#playRecorded').onclick=playRecorded; $('#voiceFile').onchange=e=>{const f=e.target.files[0]; if(!f)return; const r=new FileReader(); r.onload=()=>{state.voiceUploads[p().n]=r.result;save();updateVoice();toast('Voice audio uploaded.');}; r.readAsDataURL(f);}; $('#aiSend').onclick=sendAI; $('#aiInput').onkeydown=e=>{if(e.key==='Enter')sendAI()}; $('#downloadQR').onclick=downloadQRCard; $('#unlock').onclick=()=>{if($('#pin').value==='JS2026'){$('#adminBox').classList.remove('locked');$('#adminStatus').textContent='Unlocked.'}else toast('Incorrect PIN.')}; $('#lock').onclick=()=>{$('#adminBox').classList.add('locked');$('#adminStatus').textContent='Locked.'}; $('#saveAdminContent').onclick=()=>{const pr=baseProv(); state.custom[pr.n]=Object.assign({},state.custom[pr.n]||{},{wisdom:$('#adminWisdom').value,story:$('#adminStory').value,focus:$('#adminFocus').value});save();updateAll();toast('Province updated.');}; $('#addAksara').onclick=()=>{const pr=baseProv(),ch=$('#newAksara').value.trim(),meaning=$('#newMeaning').value.trim(); if(!ch||!meaning){toast('Add symbol and meaning.');return} const cur=state.custom[pr.n]||{}; cur.samples=cur.samples||p().samples.slice(); cur.samples.push({ch,meaning,en:`${pr.name} uses ${ch} to express ${meaning}.`,id:`${pr.name} menggunakan ${ch} untuk mengekspresikan ${meaning}.`}); state.custom[pr.n]=cur; save(); updateAll();}; $('#addMaterial').onclick=()=>{const title=$('#materialTitle').value.trim(),body=$('#materialBody').value.trim(); if(!title||!body){toast('Add title and content.');return} state.materials[p().n]=state.materials[p().n]||[]; state.materials[p().n].push({title,body});save();renderMaterials();}; $('#resetApp').onclick=()=>{state.progress={};save();updateAll();}; $('#exportState').onclick=()=>downloadBlob(JSON.stringify(state,null,2),'aksantara-state.json','application/json'); $$('.board').forEach(b=>b.onclick=()=>{$('#modalImg').src=b.dataset.img;$('#modal').classList.add('open')}); $('#closeModal').onclick=()=>$('#modal').classList.remove('open'); window.speechSynthesis.onvoiceschanged=renderVoices;}
load();renderZones();wire();updateAll();

/* === FINAL PROFESSIONAL BEHAVIOR PATCH === */
function renderMap(){
  renderCards();
  const layer=$('#hotspotLayer');
  layer.innerHTML=PROVINCES.map(pr=>`<button class="hotspot ${pr.n===state.province?'active':''}" style="left:${pr.x}%;top:${pr.y}%" data-prov="${pr.n}" aria-label="Select ${pr.name}" title="${pr.n}. ${pr.name}"></button>`).join('');
  const pr=p();
  $('#selectedChips').innerHTML=`<button class="chip" data-prov="${pr.n}">Province ${pr.n}: ${pr.name}</button><button class="chip" data-prov="${pr.n}">${pr.region}</button><button class="chip" data-go="studio">Aksara Studio: ${pr.aksara}</button><button class="chip" data-go="skills">Skills Lab: ${pr.wisdom}</button><button class="chip" data-go="voice">Voice Atlas linked</button><button class="chip" data-go="qr">QR linked</button>`;
}
function renderZones(){
 const zones=[
  ['01','Aksara Nusantara','Script recognition, manuscript literacy, and heritage families across the archipelago.','Aksara Studio','studio','📜'],
  ['02','Suara & Cerita','Oral stories, legends, listening practice, and authentic pronunciation awareness.','Voice Atlas','voice','🎙️'],
  ['03','Diversity in Communication','Language awareness, empathy, intercultural dialogue, and identity negotiation.','Skills Lab','skills','🌐'],
  ['04','English for the World','Vocabulary, reading, speaking, writing, and global communication tasks.','Integrated Skills','skills','📘'],
  ['05','AI & Future Learning','Offline ethical AI prompts, adaptive feedback, and future-ready skills.','AI Tutor','ai','AI'],
  ['06','Nusantara English Futures','Creative projects, QR discovery, dossier, and innovation outputs.','QR + Dossier','qr','✦']];
 $('#zoneGrid').innerHTML=zones.map(z=>`<article class="zoneCard"><div class="zoneIcon">${z[5]}</div><small>${z[0]}</small><h3>${z[1]}</h3><p>${z[2]}</p><button class="btn" data-go="${z[4]}">${z[3]} ›</button></article>`).join('');
}
function phraseSamples(){
  const ss=samples();
  const phrase=[];
  // prioritize explicit user sample sequence if available, otherwise workspace content
  const text=$('#workspace')?$('#workspace').textContent.trim():'';
  if(text){
    const sorted=[...ss].sort((a,b)=>b.ch.length-a.ch.length);
    let i=0;
    while(i<text.length){
      const ch=text[i];
      if(/\s/.test(ch)){i++;continue}
      const hit=sorted.find(s=>text.startsWith(s.ch,i));
      if(hit){phrase.push(hit); i+=hit.ch.length; continue;}
      phrase.push({ch,meaning:`unregistered symbol ${ch}`,en:`${ch} is not yet registered in this province bank.`,id:`${ch} belum terdaftar dalam bank aksara provinsi ini.`});
      i++;
    }
  }
  return phrase;
}
function translateWorkspace(showToast=true){
  const pr=p();
  const arr=phraseSamples();
  if(!arr.length){$('#translationBox').innerHTML='<b>Meaning / Translation:</b><br>Click aksara samples or type them in the workspace. The translation will follow the written symbols.';return}
  const syms=arr.map(s=>s.ch).join(' ');
  const meanings=arr.map(s=>s.meaning).join(' • ');
  const enLines=arr.map((s,i)=>`${i+1}. ${s.en || `${s.ch} represents ${s.meaning} in ${pr.aksara}.`}`).join('<br>');
  const idLines=arr.map((s,i)=>`${i+1}. ${s.id || `${s.ch} merepresentasikan ${s.meaning} dalam ${pr.aksara}.`}`).join('<br>');
  const enSentence=`${pr.name} uses ${pr.aksara} to express ${arr.map(s=>s.meaning).filter(Boolean).join(', ')} through ${pr.wisdom}.`;
  const idSentence=`${pr.name} menggunakan ${pr.aksara} untuk mengekspresikan ${arr.map(s=>s.meaning).filter(Boolean).join(', ')} melalui ${pr.wisdom}.`;
  $('#translationBox').innerHTML=`<b>Written Aksara:</b> ${syms}<br><b>Meaning sequence:</b> ${meanings}<br><br><b>EN sentence:</b> ${enSentence}<br><b>ID sentence:</b> ${idSentence}<br><br><b>Sample-by-sample meaning:</b><br>${enLines}<br><br><b>Makna per sampel:</b><br>${idLines}`;
  if(showToast)toast('Translation generated from the actual written aksara symbols.');
}
function applySample(i){
  const s=samples()[i]; if(!s)return;
  if(!state.selectedSamples.includes(i)) state.selectedSamples.push(i);
  insertAtCursor(s.ch + ' ');
  save(); renderSamples(); translateWorkspace(false); toast(`${s.ch} inserted into studio.`);
}
function updateStudio(){
  const pr=p(); $('#studioSelect').value=pr.n; $('#studioTitle').textContent=`${pr.name} — ${pr.aksara}`;
  $('#studioDesc').innerHTML=`Click the aksara samples, use Space / Line Break / Delete, or type directly. Translation is generated from the symbols written in the workspace for <b>${pr.name}</b>.`;
  renderSamples(); translateWorkspace(false);
}
function updateVoice(){
 const pr=p(); $('#voiceSelect').value=pr.n; $('#voiceTitle').textContent=`${pr.name} Voice Atlas`;
 $('#voiceSentence').innerHTML=`<b>Accent profile:</b> ${pr.focus}.<br><b>Model line:</b> ${pr.name} connects ${pr.aksara} and ${pr.wisdom} with clear intercultural English communication.`;
 $('#pronFocus').innerHTML=`<b>Province voice focus:</b> ${pr.focus}<br><b>Practice mode:</b> use natural browser voice, then record/upload a local accent sample for this province.`;
 const sc=state.recordings[pr.n]||state.voiceUploads[pr.n]?88:0; $('#voiceScoreBar').style.width=sc+'%'; $('#voiceScore').textContent=sc?`Local accent sample available. Estimated clarity ${sc}%.`:'No local sample yet. Record or upload a province accent sample.'; renderVoices();
}
function speakText(text){
  speechSynthesis.cancel(); const pr=p(); const u=new SpeechSynthesisUtterance(text);
  const idx=$('#voiceChoice').value; if(idx!==''&&voices[idx])u.voice=voices[idx];
  if(!u.voice){
    const preferred=voices.find(v=>/en-|English/i.test(v.lang+' '+v.name))||voices.find(v=>/id|Indonesia/i.test(v.lang+' '+v.name));
    if(preferred)u.voice=preferred;
  }
  u.lang=(u.voice&&u.voice.lang)||'en-US'; u.rate=.82; u.pitch=.98;
  speechSynthesis.speak(u); $('#voiceStatus').textContent=`Playing natural browser voice. For authentic ${pr.name} accent, record or upload a local sample.`;
}
function updateAI(){
 const pr=p();
 if(!$('#chat').dataset.prov || $('#chat').dataset.prov!=String(pr.n)){
   $('#chat').dataset.prov=pr.n;
   $('#chat').innerHTML=`<div class="msg"><b>AKSANTARA AI:</b> Welcome. I can help with ${pr.name}, ${pr.aksara}, ${pr.wisdom}, vocabulary, speaking prompts, writing models, translations, and feedback. No API key is required.</div>`;
 }
 $('#promptButtons').innerHTML=['Create a speaking prompt','Explain the local wisdom','Give five vocabulary words','Make a writing model','Design an intercultural question','Give feedback on my paragraph','Translate my written aksara'].map(x=>`<button class="prompt" data-prompt="${x}">${x}</button>`).join('');
}
function aiAnswer(q){
 const pr=p(); const low=q.toLowerCase(); const written=$('#workspace')?.textContent.trim()||'';
 if(low.includes('translate')){ if(written){translateWorkspace(false); return `I translated the current Aksara Studio text for ${pr.name}. See the Meaning / Translation panel for EN–ID results.`} return `Please write or click aksara samples in Aksara Studio first, then ask me to translate.`; }
 if(low.includes('vocab'))return `Five academic keywords for ${pr.name}: local wisdom, script heritage, intelligibility, intercultural identity, ethical technology.`;
 if(low.includes('story'))return `Story model: ${pr.story} represents ${pr.wisdom}. In English learning, it can become a listening text, a cultural reading passage, and a speaking prompt for international visitors.`;
 if(low.includes('speaking'))return `Speaking prompt: In 90 seconds, explain how ${pr.aksara} and ${pr.wisdom} help ${pr.name} communicate with the world without losing local identity.`;
 if(low.includes('writing'))return `Writing model: ${pr.name} demonstrates how ${pr.aksara} can carry local wisdom into global English learning. Through ${pr.story.toLowerCase()}, learners connect cultural memory, intelligibility, and intercultural communication.`;
 if(low.includes('feedback'))return `Feedback checklist: thesis clarity, cultural accuracy, example from ${pr.story}, transition quality, vocabulary precision, and intelligible audience-oriented phrasing.`;
 return `${pr.name} integrates ${pr.aksara}, ${pr.wisdom}, and English learning. I can help turn it into a listening task, speaking prompt, reading passage, vocabulary bank, or writing assessment.`;
}
function sendAI(){const q=$('#aiInput').value.trim(); if(!q)return; $('#chat').insertAdjacentHTML('beforeend',`<div class="msg"><b>You:</b> ${q}</div><div class="msg"><b>AKSANTARA AI:</b> ${aiAnswer(q)}</div>`); $('#aiInput').value=''; $('#chat').scrollTop=$('#chat').scrollHeight;}
function renderTask(){const pr=p(), sk=state.skill, key=pr.n+'-'+sk; let html=''; if(sk==='Listening') html=`<h3>Listening Assessment: ${pr.story}</h3><p>Listen to the line, then answer the comprehension question.</p><button class="btn primary" data-speak="The province teaches cultural communication through ${pr.wisdom}.">Play Listening Text</button><button class="choice" data-answer="1">The province teaches cultural communication through local wisdom.</button><button class="choice" data-answer="0">The province rejects English learning.</button><button class="choice" data-answer="0">The province has no oral tradition.</button>`; if(sk==='Speaking') html=`<h3>Speaking Performance Task</h3><p>Record orally or draft a 50-word speaking script explaining how ${pr.name} can share ${pr.wisdom} internationally.</p><textarea class="taskInput" id="assessmentText" placeholder="Write at least 50 words before submission..."></textarea><button class="btn primary" data-submit-text="50">Submit Speaking Performance</button>`; if(sk==='Reading') html=`<h3>Reading Comprehension</h3><p>${pr.name} uses ${pr.aksara} and ${pr.story.toLowerCase()} to connect local identity with global English communication. Learners analyze how local knowledge becomes a bridge for intercultural understanding.</p><button class="choice" data-answer="1">Local identity can support global communication.</button><button class="choice" data-answer="0">Local identity must be removed.</button>`; if(sk==='Writing') html=`<h3>Academic Writing Task</h3><p>Write a 100-word academic paragraph about ${pr.aksara}, ${pr.wisdom}, and English learning.</p><textarea class="taskInput" id="assessmentText" placeholder="Write at least 100 words before submission..."></textarea><button class="btn primary" data-submit-text="100">Submit Writing Assessment</button>`; if(sk==='Vocabulary') html=`<h3>Vocabulary Assessment</h3><p>Type seven keywords related to ${pr.wisdom}, separated by commas, then explain one keyword orally or in writing.</p><input class="taskInput" id="assessmentText" placeholder="heritage, identity, intelligibility, ..."><button class="btn primary" data-submit-vocab="7">Submit Vocabulary Set</button>`; if(sk==='Intercultural') html=`<h3>Intercultural Reflection</h3><p>How can ${pr.name} share ${pr.wisdom} with international audiences without losing local identity?</p><textarea class="taskInput" id="assessmentText" placeholder="Write at least 70 words before submission..."></textarea><button class="btn primary" data-submit-text="70">Submit Reflection</button>`; $('#taskContent').innerHTML=html+(state.progress[key]?'<p class="ok">Assessment submitted and recorded.</p>':'');}
// re-render with final patched functions
renderZones(); updateAll();
